def ql_demo_myql_oracle(page):
    state = page.evaluate('() => $state')
    
    assert not True or page.locator('#theAge_div_17').is_visible(), 'true evaluated to true, however theAge_div_17 was not displayed'
    assert not True or page.locator('#theAge2_div_92').is_visible(), 'true evaluated to true, however theAge2_div_92 was not displayed'
    assert not True or page.locator('#ofAge_div_178').is_visible(), 'true evaluated to true, however ofAge_div_178 was not displayed'
    assert not True or page.locator('#ofAge2_div_282').is_visible(), 'true evaluated to true, however ofAge2_div_282 was not displayed'
    assert not (True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) or page.locator('#hourlyRate_div_533').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 evaluated to true, however hourlyRate_div_533 was not displayed'
    assert not ((True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) and (state['hourlyRate'] <= 5)) or page.locator('#lowRemark_div_688').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 && hourlyRate <= 5 evaluated to true, however lowRemark_div_688 was not displayed'
    assert not (((True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) and (not (((state['hourlyRate'] <= 5))))) and (state['hourlyRate'] <= 15)) or page.locator('#averageRemark_div_801').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 && !(hourlyRate <= 5) && hourlyRate <= 15 evaluated to true, however averageRemark_div_801 was not displayed'
    assert not (((True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) and (not (((state['hourlyRate'] <= 5))))) and (not (((state['hourlyRate'] <= 15))))) or page.locator('#highRemark_div_893').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 && !(hourlyRate <= 5) && !(hourlyRate <= 15) evaluated to true, however highRemark_div_893 was not displayed'
    assert not (True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) or page.locator('#hoursAWeek_div_979').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 evaluated to true, however hoursAWeek_div_979 was not displayed'
    assert not (True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) or page.locator('#weeklyIncome_div_1050').is_visible(), 'true && theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2 evaluated to true, however weeklyIncome_div_1050 was not displayed'
    assert state['weeklyIncome'] == (state['hourlyRate'] * state['hoursAWeek']) if (True and ((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2']))) else True, ' weeklyIncome was expected to be hourlyRate * hoursAWeek which equals ' + str((state['hourlyRate'] * state['hoursAWeek'])) + ', but  weeklyIncome was  ' + str(state['weeklyIncome'])
    assert not (True and (not ((((((state['theAge'] >= 18) and (state['ofAge'] == True)) and (state['ofAge'] == state['ofAge2'])) and (state['theAge'] == state['theAge2'])))))) or page.locator('#theAgeToYoung_div_1200').is_visible(), 'true && !(theAge >= 18 &&        ofAge == true &&        ofAge == ofAge2 &&        theAge == theAge2) evaluated to true, however theAgeToYoung_div_1200 was not displayed'
